// Extract description from a LinkedIn job page's JobPosting JSON-LD block.
// LinkedIn ships structured data on most public job pages even unauth — this is
// the cheapest recovery path. Fallback path (Apify detail actor) is out of scope
// for this draft.

const minBody = $('Set: Config').first().json.min_body_length || 200;

const decodeEntities = (s) => String(s || '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&nbsp;/g, ' ');

const stripTags = (s) => String(s || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n\n')
  .replace(/<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const extractJobPosting = (html) => {
  if (!html || typeof html !== 'string') return null;
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  const blocks = [];
  while ((m = re.exec(html)) !== null) {
    try {
      const parsed = JSON.parse(m[1].trim());
      blocks.push(parsed);
    } catch (e) {
      // skip malformed blocks
    }
  }
  const flat = blocks.flatMap(b => Array.isArray(b) ? b : [b]);
  return flat.find(b => b && (b['@type'] === 'JobPosting' || (Array.isArray(b['@type']) && b['@type'].includes('JobPosting'))));
};

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const orig = $('Postgres: Select Quarantined LinkedIn').itemMatching(i)?.json || {};
  const httpItem = items[i].json;
  const html = typeof httpItem === 'string' ? httpItem : (httpItem.data || httpItem.body || '');
  const statusCode = items[i].json?.statusCode ?? null;

  const base = {
    id: orig.id,
    url: orig.url,
    title: orig.title,
    company: orig.company,
    http_status: statusCode
  };

  const jp = extractJobPosting(html);
  if (!jp || !jp.description) {
    out.push({ json: { ...base, recovered: false, reason: 'no_jobposting_jsonld', body_length: 0 } });
    continue;
  }

  const desc = stripTags(decodeEntities(jp.description));
  if (desc.length < minBody) {
    out.push({ json: { ...base, recovered: false, reason: `too_short_${desc.length}`, body_length: desc.length } });
    continue;
  }

  out.push({ json: { ...base, recovered: true, description: desc, body_length: desc.length, body_preview: desc.slice(0, 240) } });
}
return out;

// Dry-run summary. No DB writes. Inspect output in n8n UI before flipping
// dry_run=false in Set: Config.
const rows = $input.all().map(i => i.json);
const recovered = rows.filter(r => r.recovered);
const failed = rows.filter(r => !r.recovered);
return [{
  json: {
    mode: 'dry_run',
    total: rows.length,
    recovered_count: recovered.length,
    failed_count: failed.length,
    recovery_rate: rows.length ? Math.round((recovered.length / rows.length) * 100) + '%' : '0%',
    recovered_samples: recovered.map(r => ({ id: r.id, title: r.title, company: r.company, body_length: r.body_length, body_preview: r.body_preview })),
    failures: failed.map(r => ({ id: r.id, title: r.title, http_status: r.http_status, reason: r.reason }))
  }
}];

// Live mode: only forward rows that actually recovered a body. Failures stay
// quarantined as-is.
return $input.all().filter(i => i.json && i.json.recovered === true);
